// Query supported commands (always use flags=0 here)
int supported = membarrier(MEMBARRIER_CMD_QUERY, 0);

// Register current thread for faster, future barriers
membarrier(MEMBARRIER_CMD_REGISTER_PRIVATE_EXPEDITED, 0);

// Optimized thread-to-thread barrier (after registration)
// Used on frequent paths, replacing full hardware barriers
membarrier(MEMBARRIER_CMD_PRIVATE_EXPEDITED, 0);

// Heavyweight barrier (affects all threads system-wide)
membarrier(MEMBARRIER_CMD_GLOBAL, 0);

// Flags example: provide hint about idle CPU states
membarrier(MEMBARRIER_CMD_GLOBAL_EXPEDITED, MEMBARRIER_FLAG_CPU_IDLE);

